REGIONS = {
    "belo-horizonte-170km": "Belo Horizonte (170 km)",
    "volta-redonda-100km": "Volta Redonda (100 km)",
    "campinas-250km": "Campinas (250 km)",
}

EXTRA_FIELDS = [
    "pilot_region_id", "pilot_region_name", "pilot_batch", "research_status", "status_reason",
    "operational_evidence", "materials_or_stock", "size_assessment", "public_contact_assessment",
    "address_assessment", "operational_address", "latitude_confirmed", "longitude_confirmed",
    "within_radius_confirmed", "suggested_distance_km_not_validated", "research_name_reference",
    "company_name_match_status", "research_sources", "research_date",
    "research_notes",
]

def sha(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

OUT.mkdir(parents=True, exist_ok=True)
with LEADS.open(encoding="utf-8-sig", newline="") as f:
    by_cnpj = {r["cnpj"]: r for r in csv.DictReader(f, delimiter=";")}

assignments = []
for cnpj, (region, status, reason, evidence, materials, size, contact, address, sources, asserted_name) in DATA.items():
    # Bioterra was an initial candidate, then omitted to preserve the ten-per-region cap while retaining P&J's overlap.
    if cnpj == "15660877000186":
        continue
    if cnpj not in by_cnpj:
        raise ValueError(f"CNPJ ausente da lista local de candidatos: {cnpj}")
    if region not in json.loads(by_cnpj[cnpj]["eligible_region_ids"]):
        raise ValueError(f"Região não aplicável ao candidato {cnpj}: {region}")
    assignments.append((cnpj, region, status, reason, evidence, materials, size, contact, address, sources, asserted_name))

# The P&J unit is a valid candidate in both intersecting prospecting circles.
assignments.append(("29055949000170", "campinas-250km", *DATA["29055949000170"][1:]))
if len(assignments) != 30:
    raise ValueError(f"Piloto deveria ter 30 vínculos candidato-região, recebeu {len(assignments)}")
if Counter(region for _, region, *_ in assignments) != Counter({"belo-horizonte-170km": 10, "volta-redonda-100km": 10, "campinas-250km": 10}):
    raise ValueError("O piloto não tem exatamente dez vínculos por região")

fields = list(by_cnpj[next(iter(by_cnpj))].keys()) + EXTRA_FIELDS
selected = OUT / "leads-ultrafine-selected-pilot-2026-10.csv"
review = OUT / "leads-ultrafine-pending-pilot-2026-10.csv"

with selected.open("w", encoding="utf-8-sig", newline="") as fsel, review.open("w", encoding="utf-8-sig", newline="") as frev:
    ws = csv.DictWriter(fsel, fieldnames=fields, delimiter=";", extrasaction="ignore")
    wr = csv.DictWriter(frev, fieldnames=fields, delimiter=";", extrasaction="ignore")
    ws.writeheader(); wr.writeheader()
    for cnpj, region, status, reason, evidence, materials, size, contact, address, sources, asserted_name in assignments:
        base = dict(by_cnpj[cnpj])
        name_matches = base["company_name"] == asserted_name or base["company_name"].startswith(asserted_name + " ") or asserted_name.startswith(base["company_name"] + " ")
        base.update({
            "pilot_region_id": region,
            "pilot_region_name": REGIONS[region],
            "pilot_batch": "PILOTO-30",
            "research_status": status,
            "status_reason": reason,
            "operational_evidence": evidence,
            "materials_or_stock": materials,
            "size_assessment": size,
            "public_contact_assessment": contact,
            "address_assessment": address,
            "operational_address": "NÃO CONFIRMADO",
            "latitude_confirmed": "",
            "longitude_confirmed": "",
            "within_radius_confirmed": "NÃO",
            "suggested_distance_km_not_validated": base.get("distance_to_eligible_region_km", ""),
            "research_name_reference": asserted_name,
            "company_name_match_status": "CORRESPONDENTE" if name_matches else "VARIANTE; CNPJ É A CHAVE DE IDENTIDADE",
            "research_sources": sources,
            "research_date": TODAY,
            "research_notes": "Distância sugerida vem de coordenada CNEFE e não foi tratada como localização operacional. Sem contato direto com a empresa.",
        })
        # The approved rule requires a proven operating point and usable public contact.
        (ws if status == "SELECIONÁVEL" else wr).writerow(base)

counts = Counter(status for _, _, status, *_ in assignments)
counts_by_region = {REGIONS[region]: dict(Counter(status for _, r, status, *_ in assignments if r == region)) for region in REGIONS}
summary = {
    "created_on": TODAY,
    "source_candidate_csv": str(LEADS.relative_to(ROOT)),
    "pilot_region_assignments": len(assignments),
    "unique_establishments": len(set(cnpj for cnpj, *_ in assignments)),
    "unique_cnpj_bases": len(set(by_cnpj[cnpj]["cnpj_base"] for cnpj, *_ in assignments)),
    "duplicate_region_assignments": len(assignments) - len(set(cnpj for cnpj, *_ in assignments)),
    "counts_by_status": dict(counts),
    "counts_by_region": counts_by_region,
    "selected_csv": {"file": selected.name, "rows": 0, "bytes": selected.stat().st_size, "sha256": sha(selected)},
    "pending_csv": {"file": review.name, "rows": len(assignments), "bytes": review.stat().st_size, "sha256": sha(review)},
}
(OUT / "pilot-metadata.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

report = f'''# Piloto da peneira ultrafina — WorkGeo\n\n**Data da pesquisa e geração:** {TODAY}.\n\n## Resultado\n\nForam avaliados 30 vínculos candidato-região (10 por região), correspondentes a {summary['unique_establishments']} CNPJs de estabelecimento e {summary['unique_cnpj_bases']} CNPJs-base. Um CNPJ-base pode manter unidades e vínculos regionais separados. A Madeireira P&J aparece em Volta Redonda e Campinas porque sua sugestão cadastral a associa aos dois recortes; isso não confirma localização operacional em nenhum deles.\n\n- Selecionadas: 0.\n- Pendentes: {counts.get('PENDENTE', 0)}.\n- Fora do perfil: {counts.get('FORA_DO_PERFIL', 0)}.\n- Fora provisoriamente do raio: {counts.get('FORA_DO_RAIO_PROVISÓRIO', 0)}.\n\nNenhuma ficha cumpriu cumulativamente evidência suficiente de operação compatível, endereço operacional individual dentro do raio e canal comercial público utilizável. Portanto, o CSV de selecionadas contém somente o cabeçalho. Os registros não selecionados permanecem no CSV de pendências com estado e justificativa explícitos.\n\n## Contagens regionais\n\n| Região | Vínculos piloto | Pendentes | Fora do perfil | Fora provisoriamente do raio | Selecionadas |\n|---|---:|---:|---:|---:|---:|\n| Belo Horizonte, 170 km | 10 | 6 | 4 | 0 | 0 |\n| Volta Redonda, 100 km | 10 | 8 | 0 | 2 | 0 |\n| Campinas, 250 km | 10 | 8 | 2 | 0 | 0 |\n\nAs distâncias herdadas do CSV de Leads são sugestões CNEFE, não medições de endereço operacional. Coordenadas confirmadas ficaram vazias em todas as fichas. Endereços RFB, inclusive complementos como CASA, não foram tratados como prova de operação; nenhum caso foi excluído apenas por complemento residencial.\n\n## Critérios aplicados\n\n1. Identidade por CNPJ de estabelecimento e agrupamento por CNPJ-base, mantendo uma linha por vínculo candidato-região.\n2. Evidência pública de atividade física/material compatível com volumetria, distinguindo fatos de inferências. CNAE e nome empresarial isolados não bastam.\n3. Porte cadastral separado de porte operacional; dados desconhecidos permanecem explícitos. Empresas grandes não foram excluídas automaticamente.\n4. Para selecionar, exige-se canal comercial público utilizável e localização operacional individual comprovada dentro do raio em linha reta. Contato cadastral, telefone de contador ou ponto sugerido não satisfazem automaticamente esses requisitos.\n5. Pesquisa em fontes públicas sem contato às empresas e sem serviços pagos. Não houve alteração/importação no CRM, Turso ou site.\n\n## Limites e correções do piloto\n\nO piloto não confirma demanda ou intenção de compra. Parte das evidências vem de cadastros e diretórios secundários; contratos e licenças provam apenas o que seus documentos descrevem, no período e endereço indicados. A CRC tem sinais fortes no site, mas o vínculo da marca ao CNPJ e o endereço operacional precisam de confirmação. A ficha 2C Construções foi retirada da cota Campinas após conferir que o CSV de candidatos a associa somente a Belo Horizonte; sua pesquisa indicou escritório em BH, sem operação volumétrica comprovada. A P&J Madeireira está representada nas duas regiões em que a base a associa, com um CNPJ de estabelecimento e duas linhas de vínculo regional.\n\nNão foi produzido arquivo de selecionadas com empresas ainda não verificadas. Os próximos 100 candidatos serão priorizados em lotes, e o critério poderá ser refinado após este piloto; qualquer mudança deve ser registrada antes de aplicar aos lotes seguintes.\n\n## Arquivos e integridade\n\n- Selecionadas: `{selected.name}` — 0 registros, {selected.stat().st_size} bytes, SHA-256 `{sha(selected)}`.\n- Pendentes/revisão: `{review.name}` — {len(assignments)} vínculos, {review.stat().st_size} bytes, SHA-256 `{sha(review)}`.\n- Metadados estruturados: `pilot-metadata.json`.\n\nCSV usa UTF-8 com BOM e separador ponto e vírgula. Fontes e data de pesquisa estão em cada linha.\n'''
(OUT / "pilot-report-2026-10.md").write_text(report, encoding="utf-8")
print(json.dumps(summary, ensure_ascii=False, indent=2))
